1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface QuoteStep {
7	  op: "quote";
8	  items: {
9	    type: KnownItemType;
10	    material?: string;
11	    enchantment?: number;
12	    cursed?: boolean;
13	  }[];
14	}
15	
16	export type Step = QuoteStep;
17	
18	export interface ScenarioResults {
19	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
20	}
21	
22	const PROCESSING_FEE = 5;
23	const BASE_PREMIUM_BY_TYPE = {
24	  sword: 100,
25	  amulet: 60,
26	  staff: 80,
27	  potion: 40,
28	  rune: 25,
29	  moonstone: 25,
30	} as const satisfies Record<string, number>;
31	
32	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
33	const FIRST_INSURANCE_SURCHARGE = 0.1;
34	
35	// Percentage arithmetic leaves values like 71.00000000000001, which would
36	// otherwise round up to 72. Settle the float noise before rounding.
37	const FLOAT_NOISE_DIGITS = 6;
38	const withoutFloatNoise = (amount: number): number =>
39	  Number(amount.toFixed(FLOAT_NOISE_DIGITS));
40	
41	const roundUpInFavourOfMHPCO = (amount: number): number =>
42	  Math.ceil(withoutFloatNoise(amount));
43	
44	type Item = QuoteStep["items"][number];
45	
46	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
47	
48	const increasedBy = (amount: number, rate: number): number =>
49	  amount * (1 + rate);
50	
51	const BLOCK_SIZE = 3;
52	const BLOCK_BASE_PREMIUM = 60;
53	
54	const allOfType = (items: Item[], type: KnownItemType): boolean =>
55	  items.every((item) => item.type === type);
56	
57	// Known-incomplete: recognises a block only when the whole policy IS one
58	// block. Policies that merely CONTAIN a block (4 runes, 3 runes + 3
59	// moonstones) are not handled yet — the pending tests will force the split.
60	const isExactlyOneBlock = (items: Item[]): boolean =>
61	  items.length === BLOCK_SIZE && allOfType(items, items[0].type);
62	
63	const sumOfBasePremiums = (items: Item[]): number =>
64	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
65	
66	const policyBasePremiumOf = (items: Item[]): number =>
67	  isExactlyOneBlock(items) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(items);
68	
69	const quotePremium = (step: QuoteStep): number =>
70	  roundUpInFavourOfMHPCO(
71	    increasedBy(policyBasePremiumOf(step.items), FIRST_INSURANCE_SURCHARGE) +
72	      PROCESSING_FEE,
73	  );
74	
75	export const runScenario = (scenario: Scenario): ScenarioResults => ({
76	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
77	});
